      "explanation": "Cross-process link."
    },
    {
      "question": "Absorption mainly in:",
      "options": [
        "Small intestine",
        "Grana",
        "Lens",
        "Anode"
      ],
      "correct_answer": "Small intestine",
      "explanation": "Digestion source."
    }
  ]
}

