      "question": "Parallel axis theorem:",
      "options": [
        "I=I_cm+Md²",
        "I=M/d",
        "I=0",
        "I=I_cm-Md²"
      ],
      "correct_answer": "I=I_cm+Md²",
      "explanation": "Shift parallel axis from CM."
    }
  ]
}

